802	            let mut worker = WorkerState::new(scheduler(
803	                4,
804	                8,
805	                128,
806	                PrefillPolicy::Chunked { max_chunk_tokens },
807	            ))
808	            .unwrap();
809	            assert_eq!(
810	                worker.submit(request(1, 0, 3)).unwrap(),
811	                SubmissionResult::Queued
812	            );
813	            assert_eq!(
814	                worker.submit(request(2, 0, 3)).unwrap(),
815	                SubmissionResult::Queued
816	            );
