823	                worker.submit(request(3, 100, 2)).unwrap(),
824	                SubmissionResult::Queued
825	            );
826	            assert_eq!(
827	                worker.submit(request(4, 1, 1)).unwrap(),
828	                SubmissionResult::Queued
829	            );
830	
831	            for _ in 0..128 {
832	                let Some(step) = record_step(&mut worker) else {
833	                    break;
834	                };
835	                steps.push(step);
836	            }
837	            assert!(worker.is_idle());
838	            let mut finished = steps
839	                .iter()
840	                .flat_map(|step| step.finished.iter().copied())
841	                .collect::<Vec<_>>();
842	            finished.sort_unstable();
843	            let mut generated = steps
844	                .iter()
845	                .flat_map(|step| step.generated.iter().copied())
846	                .collect::<Vec<_>>();
847	            generated.sort_unstable();
848	            Replay {
849	                steps,
850	                finished,
851	                generated,
852	            }
853	        }
