    pub manifest_path: PathBuf,
}

impl LoadedEngineProfile {
    pub fn validate(&self) -> Result<()> {
        self.profile.validate()?;
        self.manifest.validate()
    }

    pub fn model_id(&self) -> &str {
        &self.manifest.model_id
